-- Part 7 (difficulty-uplift pass): online MCQ bank (comp_mcq_questions) hard (difficulty=3) items
-- for hse_specialist and site_supervisor. Root cause: population-wide MCQ ceiling effect (5 SCORED
-- tests averaging 84.7%, min 76.7%, zero below 60%) vs the same candidates averaging only 3.0/5
-- (60%) on the human panel — a ~25-point gap pointing at insufficient MCQ discrimination power.
-- comp_mcq_generate_test() draws a fixed 30/45/25% easy/medium/hard quota per role (schema.sql
-- Section 56); roles thin on hard items fall back to padding the quota with easier questions,
-- silently diluting the intended difficulty mix. hse_specialist was at 8/43 hard (18.6%) and
-- site_supervisor at 8/42 hard (19.0%) — both well under the ~25% design quota and the bank-wide
-- ~24% hard share. This adds 9 hard items to each role (all new topics or new items on existing
-- hard topics, none duplicating an existing stem), bringing each to roughly 32-33% hard share.
-- Item design: multi-step/numeric-adjacent items (OSHA excavation slope-angle table, confined-space
-- O2/LEL testing sequence), and scenario/judgment items requiring weighing two plausible actions
-- against a specific code clause (LOTO group lockout, PSM MOC vs like-for-like, ICS span of
-- control) rather than single-fact recall. Domain grounding: OSHA 1910.146/1910.147/1910.119(l),
-- OSHA 1926 Subpart P Appendix B, NFPA 51B, ASME B30.5, FEMA ICS/NIMS for hse_specialist; ASME
-- B31.3 piping class, ITP hold/witness point conventions, ASME B30.5 crane pre-use inspection, and
-- construction sequencing practice for site_supervisor. Anti-guessability: correct_option is
-- rotated 0..3 across rows via the same technique as supabase/seed/mcq_questions_seed.sql (no
-- fixed "always C/D" pattern), and no two items share a scenario shape with only a domain noun
-- swapped between the two roles. Idempotent via (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'hse_specialist', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
from jsonb_array_elements($mcq$[
["TECHNICAL", "ایمنی برق و LOTO", 3, "در یک عملیات تعمیراتی که چند تیم مختلف به‌طور هم‌زمان روی یک خط تحت پرمیت کار فعالیت می‌کنند، کدام روش قفل و برچسب (LOTO) برای گروه چندنفره صحیح است؟", ["فقط سرپرست یک قفل روی نقطه ایزوله می‌زند و به همه اعلام می‌کند", "هر یک از پرسنل مجاز قفل شخصی خود را روی جعبه قفل گروهی (Group Lockout Box) نصب می‌کند تا انرژی تا برداشتن آخرین قفل بازیابی نشود", "فقط با تگ کاغذی بدون قفل فیزیکی اکتفا می‌شود", "هر تیم به‌صورت شفاهی هماهنگی می‌کند و نیازی به قفل فیزیکی نیست"], 1, "در LOTO گروهی، هر پرسنل مجاز باید قفل شخصی خود را روی جعبه قفل گروهی نصب کند تا انرژی تا زمانی که همه (از جمله آخرین نفر) قفل خود را برنداشته‌اند بازیابی نشود؛ تکیه به یک قفل سرپرست یا هماهنگی شفاهی کنترل کافی ایجاد نمی‌کند.", "OSHA 1910.147 (Group Lockout Procedures)"],
["TECHNICAL", "تست گاز (Gas Testing)", 3, "ترتیب صحیح آزمایش اتمسفر پیش از ورود به فضای محصور و محدوده قابل قبول غلظت اکسیژن کدام است؟", ["ابتدا گازهای سمی، سپس قابل‌اشتعال، سپس اکسیژن؛ محدوده اکسیژن ۱۶ تا ۲۵ درصد", "ابتدا اکسیژن، سپس گازهای قابل‌اشتعال، سپس گازهای سمی؛ محدوده قابل قبول اکسیژن ۱۹.۵ تا ۲۳.۵ درصد", "ترتیب اهمیتی ندارد؛ فقط باید عدد قابل‌اشتعال زیر ۵۰٪ LEL باشد", "فقط بوی محیط برای تشخیص ایمنی اتمسفر کافی است"], 1, "استاندارد آزمایش اتمسفر فضای محصور ابتدا اکسیژن (برای اطمینان از کافی بودن برای تنفس و عدم غنی‌شدگی خطرناک)، سپس گازهای قابل‌اشتعال، و سپس گازهای سمی را می‌سنجد؛ محدوده قابل قبول اکسیژن ۱۹.۵ تا ۲۳.۵ درصد است.", "OSHA 1910.146 Appendix B (Permit-Required Confined Spaces)"],
["TECHNICAL", "حفاری و گودبرداری", 3, "طبق جدول شیب مجاز OSHA 1926 Subpart P، حداکثر شیب دیواره ترانشه بدون شمع‌بندی برای خاک نوع A (Type A) در گودبرداری موقت کدام است؟", ["۳۴ درجه (نسبت تقریبی ۱.۵ به ۱)، مخصوص خاک نوع C", "۴۵ درجه (نسبت ۱ به ۱)، مخصوص خاک نوع B", "۵۳ درجه (نسبت تقریبی ۳ به ۴)، مخصوص خاک نوع A", "۹۰ درجه (دیواره قائم) برای همه انواع خاک"], 2, "خاک نوع A پایدارترین طبقه در جدول شیب‌بندی OSHA است و حداکثر شیب مجاز بدون شمع‌بندی حدود ۵۳ درجه (نسبت تقریبی ۳ افقی به ۴ عمودی) دارد؛ خاک نوع B حدود ۴۵ درجه و نوع C حدود ۳۴ درجه مجاز است.", "OSHA 1926 Subpart P, Appendix B"],
["HSE", "پرمیت کار گرم (Hot Work)", 3, "پس از اتمام عملیات جوشکاری/برشکاری گرم در ناحیه‌ای با احتمال وجود مواد قابل‌اشتعال پنهان، رویه استاندارد Fire Watch چه مدت زمانی را برای پایش پس از پایان کار توصیه می‌کند؟", ["بلافاصله پس از خاموش کردن مشعل، بدون نیاز به پایش بیشتر", "حداقل ۳۰ دقیقه پایش مستمر محل پس از پایان کار گرم، پیش از ترک ناحیه", "فقط ۵ دقیقه برای اطمینان از خاموش شدن شعله", "پایش فقط توسط جوشکار و فقط در صورت درخواست او"], 1, "رویه استاندارد Fire Watch ایجاب می‌کند ناظر آتش حداقل ۳۰ دقیقه پس از پایان کار گرم در محل بماند و پایش کند، چون احتراق تاخیری بقایای گرم یا جرقه‌های پنهان می‌تواند دیرتر رخ دهد؛ در کارهای پرریسک‌تر این مدت بر اساس ارزیابی ریسک افزایش می‌یابد.", "NFPA 51B (Fire Watch Requirements)"],
["JUDGMENT", "مدیریت تغییر (MOC)", 3, "کدام یک از موارد زیر، طبق اصول مدیریت تغییر (MOC) در چارچوب مدیریت ایمنی فرآیند (PSM)، نیازمند بررسی و تایید رسمی MOC است و «جایگزینی مشابه» (Replacement in Kind) محسوب نمی‌شود؟", ["تعویض یک شیر خراب با شیر دیگری از همان سازنده، مشخصات فنی و رتبه فشاری یکسان", "نصب شیر اطمینان جدید با ظرفیت تخلیه و تنظیمات متفاوت از طراحی اصلی فرآیند", "تعویض یک لامپ روشنایی سوخته در اتاق کنترل با نمونه مشابه", "تعویض فیلتر مصرفی یک پمپ با فیلتر استاندارد همان مدل طبق دستورالعمل سازنده"], 1, "تغییر در ظرفیت یا تنظیمات یک تجهیز ایمنی فرآیندی (مثل شیر اطمینان) نسبت به طراحی پایه، یک تغییر فرآیندی واقعی است و باید از مسیر MOC با بررسی مهندسی و ایمنی رسمی عبور کند؛ سایر گزینه‌ها جایگزینی دقیقاً مشابه (Like-for-Like) هستند.", "OSHA 1910.119(l) — Management of Change"],
["SCENARIO", "عملیات بالابری", 3, "در حین یک عملیات بالابری با جرثقیل موبایل، سرعت باد به‌طور محسوس افزایش می‌یابد و نزدیک به محدودیت اعلام‌شده در جدول بار (Load Chart) سازنده می‌رسد. اقدام درست اپراتور/سرپرست کدام است؟", ["ادامه‌ی بالابری با همان سرعت برای اتمام سریع‌تر کار پیش از تشدید باد", "توقف عملیات و ارزیابی مجدد طبق محدودیت‌های باد جدول بار سازنده پیش از ادامه", "کاهش شعاع بالابری بدون بررسی جدول بار برای جبران اثر باد", "ادامه‌ی کار فقط با افزایش هوشیاری راهنما (Signalman)، بدون توقف"], 1, "جدول بار جرثقیل محدودیت‌های مشخصی برای سرعت باد دارد که فراتر از آن، ظرفیت مؤثر و پایداری بار به‌طور خطرناکی کاهش می‌یابد؛ نزدیک‌شدن به این آستانه باید با توقف و ارزیابی مجدد، نه ادامه‌ی کار، پاسخ داده شود.", "ASME B30.5 / دستورالعمل ایمنی عملیات بالابری"],
["TECHNICAL", "مدیریت شرایط اضطراری", 3, "در سیستم فرماندهی حادثه (Incident Command System - ICS) هنگام مدیریت یک حادثه اضطراری بزرگ در سایت، دامنه کنترل (Span of Control) مطلوب برای هر سرپرست/فرمانده بخش معمولاً چند نفر توصیه می‌شود؟", ["۱ تا ۲ نفر برای حداکثر دقت", "۳ تا ۷ نفر، با مقدار بهینه‌ی حدود ۵ نفر", "۱۵ تا ۲۰ نفر برای کاهش سطوح سازمانی", "محدودیتی وجود ندارد و به تعداد کل پرسنل حاضر بستگی دارد"], 1, "اصل دامنه کنترل در ICS توصیه می‌کند هر سرپرست ۳ تا ۷ نفر (با مقدار بهینه‌ی حدود ۵ نفر) را مدیریت کند تا هماهنگی و ایمنی حفظ شود؛ فراتر از این محدوده، کنترل و ارتباط مؤثر دشوار می‌شود.", "FEMA ICS / NIMS — Span of Control"],
["PROBLEM_SOLVING", "تحقیق حادثه و RCA", 3, "یک نوع خاص از شبه‌حادثه (Near Miss) طی چند شیفت متفاوت با پرسنل مختلف روی یک فعالیت مشخص در سایت تکرار می‌شود. اولین گام تحلیلی درست کدام است؟", ["تذکر انضباطی به تک‌تک کارگران درگیر در هر رویداد", "بررسی کفایت JSA/دستورالعمل اجرایی آن فعالیت برای شناسایی یک علت ریشه‌ای سیستمی مشترک", "نادیده گرفتن چون شبه‌حادثه آسیبی ایجاد نکرده است", "افزایش صرف تعداد ناظران بدون بررسی فرآیند کار"], 1, "تکرار یک الگوی مشابه با پرسنل متفاوت نشانه‌ی یک علت ریشه‌ای سیستمی (نقص در روش کار، JSA یا طراحی فرآیند) است، نه خطای فردی؛ برخورد انضباطی صرف یا افزودن ناظر بدون اصلاح ریشه، تکرار را متوقف نمی‌کند.", "رویه تحلیل علت ریشه‌ای (RCA) حوادث HSE"],
["TECHNICAL", "نظارت HSE بر پیمانکار", 3, "پیش از اجازه‌ی شروع یک فعالیت پرریسک توسط پیمانکار جزء (مثل کار در ارتفاع یا فضای محصور)، کدام گزینه مهم‌ترین بررسی نظارتی HSE است؟", ["فقط دریافت فاکتور مالی قرارداد پیمانکار", "راستی‌آزمایی صلاحیت/آموزش پرسنل، تطابق ارزیابی ریسک پیمانکار با شرایط واقعی سایت، و انطباق با سیستم پرمیت کار پروژه", "اتکای کامل به گواهی‌نامه‌های عمومی پیمانکار بدون بررسی محلی", "اجازه‌ی شروع کار و بازرسی فقط در پایان روز"], 1, "نظارت مؤثر HSE بر پیمانکار پیش از شروع کار پرریسک نیازمند راستی‌آزمایی مستقل صلاحیت پرسنل، تطبیق ارزیابی ریسک با شرایط واقعی سایت (نه فقط سند عمومی)، و یکپارچگی با سیستم پرمیت کار میزبان است.", "ISO 45001 / رویه مدیریت HSE پیمانکار"]
]$mcq$::jsonb) with ordinality t(x, n)
cross join lateral (select ((((n - 1) % 4)::int - (x ->> 5)::int + 4) % 4) as k) r
on conflict (job_role, md5(stem_fa)) do nothing;

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'site_supervisor', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
from jsonb_array_elements($mcq$[
["TECHNICAL", "خواندن نقشه‌های ایزومتریک و P&ID", 3, "در نقشه ایزومتریک یک خط لوله، علامت یک فلنج با کلاس فشار #300 دیده می‌شود در حالی که اسپول مجاور از کلاس #150 است. تفسیر صحیح این وضعیت چیست؟", ["خطای چاپی نقشه است و می‌توان بدون بررسی نادیده گرفت", "نشان‌دهنده‌ی یک تغییر کلاس فشار (Rating Change) طراحی‌شده در آن نقطه است که باید طبق نقشه/اسپک خط تایید و دقیقاً اجرا شود", "همیشه به معنی خطای طراحی است که باید بدون استعلام رد شود", "فقط بر رنگ شناسایی لوله تاثیر دارد"], 1, "تغییر کلاس فشار در طول یک خط امری رایج و عمداً طراحی‌شده در نقاطی مانند اتصال به تجهیز یا شیر است؛ سرپرست باید این تغییر را با نقشه ایزومتریک و اسپک خط (Line List/Piping Class) تطبیق دهد، نه آن را خطا فرض کند یا نادیده بگیرد.", "خواندن نقشه ایزومتریک و Piping Class / ASME B31.3"],
["TECHNICAL", "نقاط توقف کیفی (Hold Point)", 3, "تفاوت کلیدی بین «نقطه توقف» (Hold Point) و «نقطه شاهد» (Witness Point) در برنامه بازرسی و آزمون (ITP) چیست؟", ["هیچ تفاوتی ندارند و هر دو الزام آور یکسان دارند", "در Hold Point، کار بدون حضور و تایید مرجع ذی‌ربط نباید ادامه یابد؛ در Witness Point، مرجع می‌تواند حضور یابد اما عدم حضورش مانع ادامه‌ی کار نیست", "Witness Point همیشه سخت‌گیرانه‌تر از Hold Point است", "هر دو فقط برای مستندسازی هستند و تاثیری بر روند اجرا ندارند"], 1, "Hold Point الزام‌آور است: بدون تایید حاضر و ناظر مربوطه، کار متوقف می‌ماند؛ Witness Point صرفاً فرصت حضور می‌دهد و عدم حضور ناظر مانع ادامه‌ی کار نیست.", "رویه ITP (Inspection & Test Plan) پروژه"],
["SCENARIO", "هماهنگی مجوز کار با HSE", 3, "در یک روز کاری، دو پرمیت کار برای فعالیت‌های همزمان (کار گرم جوشکاری و کار در ارتفاع روی داربست مجاور) در فاصله نزدیک به هم صادر شده است. اقدام درست سرپرست کارگاه چیست؟", ["اجرای هر دو کار بدون هماهنگی چون هر کدام پرمیت جداگانه دارند", "بررسی تداخل خطرات دو فعالیت (مثل ریسک جرقه روی داربست/مواد قابل اشتعال) و هماهنگی/توالی یا فاصله ایمن پیش از اجرای همزمان", "لغو کامل هر دو پرمیت بدون بررسی", "واگذاری هماهنگی کامل به تیم‌های اجرایی بدون دخالت سرپرست"], 1, "صدور جداگانه‌ی پرمیت برای هر فعالیت، تداخل خطرات بین فعالیت‌های همزمان و نزدیک به هم را پوشش نمی‌دهد؛ سرپرست باید این تداخل را شناسایی و با توالی‌بندی یا فاصله/کنترل اضافی مدیریت کند.", "رویه سیستم پرمیت کار (PTW) و کار همزمان (SIMOPS)"],
